                    sb.append('\'');
                    break;
                case 'u':
                    sb.append((char) Integer.parseInt(str.substring(i + 1, i + 5), 16));
                    i += 4;
                    break;
                case 'U':
                    sb.append((char) Integer.parseInt(str.substring(i + 1, i + 9), 16));
